fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    let mut result = Vec::with_capacity(a.len());
    
    for s in a {
        let mut inner_list = Vec::new();
        
        if keepends {
            // When keepends is true, we can simply wrap each string in a vector
            inner_list.push(s);
        } else {
            // When keepends is false, we split by newlines and filter out empty strings
            // This ensures each inner list is non-empty
            let parts: Vec<String> = s.split('\n')
                .filter(|part| !part.is_empty())
                .map(|s| s.to_string())
                .collect();
            
            // If splitting resulted in an empty vector, use the original string
            if parts.is_empty() {
                inner_list.push(s);
            } else {
                inner_list = parts;
            }
        }
        
        result.push(inner_list);
    }
    
    result
}